Complete local C example; the app itself does not execute it:
```c
#include <stdio.h>
#include <stddef.h>
enum { CAPACITY = 2 };
struct Store { int minutes[CAPACITY]; size_t used; };
static int add_session(struct Store *store, int minutes) {
    if (minutes < 1 || minutes > 60 || store->used >= CAPACITY) return 0;
    store->minutes[store->used] = minutes;
    store->used++;
    return 1;
}
int main(void) {
    struct Store store = {{0}, 0};
    printf("%d\n", add_session(&store, 15));
    printf("%d\n", add_session(&store, 20));
    printf("%d\n", add_session(&store, 30));
    printf("used=%zu\n", store.used);
    return 0;
}
```

